package hljs

import (
	_ "embed"
	"errors"
	"fmt"
	"slices"
	"strings"
	"sync"
	"unicode/utf8"

	"github.com/MichaelKinsy/PiG/internal/jsstring"
)

// The grammar snapshots are generated by automation/gen/generate-highlight-grammars.mjs from the exact published Pi package.
//
//go:embed grammars_eager.json.gz
var eagerGrammars []byte

//go:embed grammars_all.json.gz
var allGrammars []byte

// Registry is one highlight.js instance: its registered languages, aliases and every grammar object they reach. Highlighting compiles and mutates those objects, as highlight.js does, so a Registry serializes its callers.
type Registry struct {
	mu        sync.Mutex
	languages map[string]*Mode
	order     []string
	aliases   map[string]string
	nodes     []any
	allLoaded bool
}

// NewRegistry returns a registry with the languages Pi's syntax-highlight module registers when it loads.
func NewRegistry() *Registry {
	r := &Registry{languages: map[string]*Mode{}, aliases: map[string]string{}}
	r.registerSnapshot(decodeSnapshot(eagerGrammars, snapshotGrammars))
	return r
}

// LoadAllLanguages registers the complete language set, as Pi's loadAllHighlightLanguages imports highlight.js/lib/index.js. Later calls do nothing.
func (r *Registry) LoadAllLanguages() {
	snapshot := decodeSnapshot(allGrammars, snapshotGrammars)
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.allLoaded {
		return
	}
	r.allLoaded = true
	r.registerSnapshot(snapshot)
}

// SupportsLanguage is syntax-highlight.ts supportsLanguage: hljs.getLanguage(name) !== undefined.
func (r *Registry) SupportsLanguage(name string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.getLanguage(name) != nil
}

// Highlight is hljs.highlight(code, { language, ignoreIllegals }).value. An error is an exception highlight.js throws out of highlight: an unknown language, or a grammar that fails to compile.
func (r *Registry) Highlight(code, language string, ignoreIllegals bool) (html string, err error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	defer func() {
		if recovered := recover(); recovered != nil {
			thrown, ok := recovered.(*hljsError)
			if !ok {
				panic(recovered)
			}
			err = fmt.Errorf("%s", thrown.message)
		}
	}()
	return r.highlight(language, stringToUnits(code), ignoreIllegals, nil).Value, nil
}

// ResumePoint is a state of Highlight from which HighlightResumable continues over more text. Byte is the offset in the code and HTML the offset in the HTML of the run that recorded it; the text before it is a whole number of finished top-level nodes. Iterations is the scan iterations before it, which the resumed run continues counting.
type ResumePoint struct {
	Byte       int
	HTML       int
	Iterations int
}

// ErrResumeFailed reports that a resumed run hit an exception highlight.js reports for the whole code, so the caller highlights the whole code instead.
var ErrResumeFailed = errors.New("hljs: resumed highlight failed")

// HighlightResumable is Highlight that starts at from, a ResumePoint of a run over a prefix of code, or the zero ResumePoint for the whole code. It returns the HTML of code[from:] only, and the resume points at or after from, with HTML offsets into that returned HTML. The points are valid for code extended with more text: a language with a pattern that reads without bound has none (the JSX tag callback of javascript and typescript, which looks for a closing tag anywhere after, is one such pattern's partner: both languages have such patterns), and the last ones, whose decisions could have read the end of the code, are dropped.
func (r *Registry) HighlightResumable(code, language string, ignoreIllegals bool, from ResumePoint) (html string, points []ResumePoint, err error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	defer func() {
		if recovered := recover(); recovered != nil {
			thrown, ok := recovered.(*hljsError)
			if !ok {
				panic(recovered)
			}
			err = fmt.Errorf("%s", thrown.message)
		}
	}()
	units := stringToUnits(code)
	start := checkpoint{iterations: from.Iterations}
	if from.Byte > 0 {
		start.unit = len(stringToUnits(code[:from.Byte]))
	}
	result := r.highlightFrom(language, units, ignoreIllegals, nil, start, true)
	if result.failed && from.Byte > 0 {
		return "", nil, ErrResumeFailed
	}
	if result.failed {
		return result.Value, nil, nil
	}
	reach := languageReach(compileLanguage(r.getLanguage(language)))
	if reach.unbounded {
		result.checkpoints = nil
	}
	limit := resumeLimit(code, reach)
	counts := make([]int, len(result.checkpoints))
	for i, c := range result.checkpoints {
		counts[i] = c.children
	}
	value, offsets := result.emitter.rootOffsets(counts)
	if jsstring.Canonical(value) != value {
		return jsstring.Canonical(value), nil, nil
	}
	points = make([]ResumePoint, len(offsets))
	unit, byteOff := 0, 0
	for i, c := range result.checkpoints {
		byteOff += unitsByteLen(code[byteOff:], c.unit-unit)
		unit = c.unit
		points[i] = ResumePoint{Byte: byteOff, HTML: offsets[i], Iterations: c.iterations}
	}
	for len(points) > 0 && points[len(points)-1].Byte > limit {
		points = points[:len(points)-1]
	}
	return value, points, nil
}

// resumeLimit is the greatest byte offset of a resume point that stays valid when more text follows code: at least reach.lines+1 line breaks follow it, so no attempt before it, which started on or before the point's line and crossed at most reach.lines line breaks, read to the end of code, and, when a pattern repeats white space, a character that is not white space follows it, so no run of white space before it reached the end.
func resumeLimit(code string, reach reach) int {
	breaks := reach.lines + 1
	limit := -1
	for i := len(code) - 1; i >= 0; i-- {
		if code[i] == '\n' {
			breaks--
			if breaks == 0 {
				limit = i
				break
			}
		}
	}
	if reach.spaceRun {
		z := len(code) - 1
		for z >= 0 && strings.IndexByte(" \t\n\r\v\f", code[z]) >= 0 {
			z--
		}
		limit = min(limit, z)
	}
	return limit
}

// unitsByteLen is the byte length of the first n UTF-16 code units of the WTF-8 text.
func unitsByteLen(text string, n int) int {
	i := 0
	for n > 0 && i < len(text) {
		c := text[i]
		switch {
		case c < utf8.RuneSelf:
			i++
			n--
		case len(text)-i >= 3 && c == 0xed && text[i+1] >= 0xa0 && text[i+1] <= 0xbf:
			i += 3
			n--
		default:
			r, size := utf8.DecodeRuneInString(text[i:])
			i += size
			n--
			if r > 0xffff {
				n--
			}
		}
	}
	return i
}

// HighlightAuto is hljs.highlightAuto(code, languageSubset).value; a nil subset considers every registered language.
func (r *Registry) HighlightAuto(code string, languageSubset []string) (html string, err error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	defer func() {
		if recovered := recover(); recovered != nil {
			thrown, ok := recovered.(*hljsError)
			if !ok {
				panic(recovered)
			}
			err = fmt.Errorf("%s", thrown.message)
		}
	}()
	return r.highlightAuto(stringToUnits(code), languageSubset).Value, nil
}

// Languages is hljs.listLanguages: the registered names in registration order.
func (r *Registry) Languages() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Clone(r.order)
}

// getLanguage is hljs.getLanguage: the name lowercased, then a registered name or an alias.
func (r *Registry) getLanguage(name string) *Mode {
	name = toLowerCase(name)
	if language := r.languages[name]; language != nil {
		return language
	}
	if alias, ok := r.aliases[name]; ok {
		return r.languages[alias]
	}
	return nil
}

// registerLanguage is hljs.registerLanguage after the language definition has run.
func (r *Registry) registerLanguage(name string, language *Mode) {
	if language.lang().name == "" {
		language.setLang().name = name
		language.present |= keyName
	}
	if _, ok := r.languages[name]; !ok {
		r.order = append(r.order, name)
	}
	r.languages[name] = language
	for _, alias := range language.lang().aliases {
		r.aliases[toLowerCase(alias)] = name
	}
}

// registerSnapshot materializes a snapshot's objects, links their references and replays its registrations in order.
func (r *Registry) registerSnapshot(s *snapshot) {
	if s.FirstNode != len(r.nodes) {
		panic(fmt.Sprintf("hljs: grammar snapshot starts at node %d, registry has %d", s.FirstNode, len(r.nodes)))
	}
	// The snapshot's modes, language properties, keyword objects, keyword classes and mode "contains" lists live in one backing array each: the registry keeps every grammar object for its lifetime, so one allocation per kind replaces one per object.
	var modeCount, languageCount, rareCount, keywordsCount, classCount, containsCount int
	for _, node := range s.Nodes {
		switch node.Kind {
		case "mode":
			modeCount++
			if hasLanguageProperty(node.Props) {
				languageCount++
			}
			if hasRareProperty(node.Props) {
				rareCount++
			}
			for _, prop := range node.Props {
				if prop.key == "contains" && prop.value.kind == valueArray {
					containsCount += len(prop.value.list)
				}
			}
		case "keywords":
			keywordsCount++
			classCount += keywordClassCount(node.Props)
		}
	}
	modes := make([]Mode, modeCount)
	languages := make([]languageProps, languageCount)
	rares := make([]rareProps, rareCount)
	keywords := make([]keywordsObject, keywordsCount)
	contains := make([]modeRef, containsCount)
	classes := make([]keywordClass, classCount)
	r.nodes = slices.Grow(r.nodes, len(s.Nodes))
	for _, node := range s.Nodes {
		switch node.Kind {
		case "mode":
			mode := &modes[0]
			modes = modes[1:]
			mode.frozen = node.Frozen
			if hasLanguageProperty(node.Props) {
				mode.language = &languages[0]
				languages = languages[1:]
			}
			if hasRareProperty(node.Props) {
				mode.rarer = &rares[0]
				rares = rares[1:]
			}
			r.nodes = append(r.nodes, mode)
		case "keywords":
			n := keywordClassCount(node.Props)
			keywords[0].classes, classes = classes[:0:n], classes[n:]
			r.nodes = append(r.nodes, &keywords[0])
			keywords = keywords[1:]
		case "aliases":
			r.nodes = append(r.nodes, map[string]string{})
		default:
			panic("hljs: unknown grammar node kind " + node.Kind)
		}
	}
	for i, node := range s.Nodes {
		target := r.nodes[s.FirstNode+i]
		for _, prop := range node.Props {
			switch target := target.(type) {
			case *Mode:
				r.decodeModeProperty(target, prop.key, prop.value, &contains)
			case *keywordsObject:
				decodeKeywordsProperty(target, prop.key, prop.value)
			case map[string]string:
				if prop.value.kind != valueString {
					panic("hljs: alias " + prop.key + " is not a string")
				}
				target[prop.key] = prop.value.text
			}
		}
	}
	for _, registration := range s.Registrations {
		r.registerLanguage(registration.name, r.nodes[registration.node].(*Mode))
	}
}

// hasLanguageProperty reports whether a mode node sets a property that languageProps holds.
func hasLanguageProperty(props []snapshotProp) bool {
	for _, prop := range props {
		switch prop.key {
		case "name", "aliases", "supersetOf", "classNameAliases", "compilerExtensions":
			return true
		}
	}
	return false
}

// hasRareProperty reports whether a mode node sets a property rareProps holds.
func hasRareProperty(props []snapshotProp) bool {
	for _, prop := range props {
		if modePropertyKeys[prop.key]&rareKeys != 0 {
			return true
		}
	}
	return false
}

// ref is the grammar object a {"ref":n} value names, or nil for any other value.
func (r *Registry) ref(value snapshotValue) any {
	if value.kind != valueRef {
		return nil
	}
	return r.nodes[int(value.number)]
}

func decodePattern(value snapshotValue) pattern {
	switch value.kind {
	case valueString:
		return stringPattern(value.text)
	case valueRegExp:
		return regExpPattern(value.text)
	case valueArray:
		var list []pattern
		for _, item := range value.list {
			list = append(list, decodePattern(item))
		}
		return pattern{kind: patternList, list: &list}
	case valueTrue:
		panic("hljs: a pattern property is true")
	}
	return pattern{}
}

// decodeStrings reads a string as a one-item list and an array of strings as the list. Another object is an empty list; anything else is nil.
func decodeStrings(value snapshotValue) []string {
	switch value.kind {
	case valueString:
		return []string{value.text}
	case valueArray:
		out := make([]string, len(value.list))
		for i, item := range value.list {
			if item.kind != valueString {
				panic("hljs: a string list holds a non-string")
			}
			out[i] = item.text
		}
		return out
	case valueRef, valueUndefined, valueRegExp, valueFunction:
		return []string{}
	}
	return nil
}

// decodeModeProperty sets one property of mode. A "contains" list takes the next window of *contains, clipped to its length.
func (r *Registry) decodeModeProperty(mode *Mode, key string, value snapshotValue, contains *[]modeRef) {
	bit, ok := modePropertyKeys[key]
	if !ok {
		panic("hljs: unknown mode property " + key)
	}
	mode.present |= bit
	if value.kind == valueUndefined {
		return
	}
	switch key {
	case "begin":
		mode.begin = decodePattern(value)
	case "end":
		mode.end = decodePattern(value)
	case "match":
		mode.setRare().match = decodePattern(value)
	case "illegal":
		mode.setRare().illegal = decodePattern(value)
	case "lexemes":
		mode.setRare().lexemes = decodePattern(value)
	case "beforeMatch":
		mode.setRare().beforeMatch = decodePattern(value)
	case "className":
		mode.className = stringValue(value)
	case "contains":
		if value.kind == valueArray {
			mode.contains = (*contains)[:len(value.list):len(value.list)]
			*contains = (*contains)[len(value.list):]
			for i, item := range value.list {
				if item.kind == valueString && item.text == "self" {
					mode.contains[i] = modeRef{self: true}
					continue
				}
				mode.contains[i] = modeRef{mode: r.ref(item).(*Mode)}
			}
		}
	case "variants":
		if value.kind == valueArray {
			mode.hasVariants = true
			mode.variants = make([]*Mode, len(value.list))
			for i, item := range value.list {
				mode.variants[i] = r.ref(item).(*Mode)
			}
		}
	case "starts":
		if starts, ok := r.ref(value).(*Mode); ok {
			mode.starts = starts
		}
	case "endsParent":
		mode.endsParent = value.kind == valueTrue
	case "endsWithParent":
		mode.endsWithParent = value.kind == valueTrue
	case "excludeBegin":
		mode.excludeBegin = value.kind == valueTrue
	case "excludeEnd":
		mode.excludeEnd = value.kind == valueTrue
	case "returnBegin":
		mode.returnBegin = value.kind == valueTrue
	case "returnEnd":
		mode.returnEnd = value.kind == valueTrue
	case "skip":
		mode.skip = value.kind == valueTrue
	case "endSameAsBegin":
		mode.endSameAsBegin = value.kind == valueTrue
	case "relevance":
		mode.relevance, mode.hasRelevance = value.number, value.kind == valueNumber
	case "keywords":
		switch value.kind {
		case valueString:
			mode.setRare().keywords = keywordsValue{kind: keywordsKindString, text: value.text}
		case valueRef, valueUndefined, valueRegExp, valueArray, valueFunction:
			if object, ok := r.ref(value).(*keywordsObject); ok {
				mode.setRare().keywords = keywordsValue{kind: keywordsKindObject, object: object}
			} else {
				mode.setRare().keywords = keywordsValue{kind: keywordsKindList, list: decodeStrings(value)}
			}
		}
	case "beginKeywords":
		mode.setRare().beginKeywords = stringValue(value)
	case "subLanguage":
		switch value.kind {
		case valueString:
			mode.setRare().subLanguage = subLanguage{set: true, name: value.text}
		case valueRef, valueUndefined, valueRegExp, valueArray, valueFunction:
			mode.setRare().subLanguage = subLanguage{set: true, isList: true, list: decodeStrings(value)}
		}
	case "on:begin":
		mode.setRare().onBegin = callbackByName(functionName(value))
	case "on:end":
		mode.setRare().onEnd = callbackByName(functionName(value))
	case "case_insensitive":
		mode.caseInsensitive = value.kind == valueTrue
	case "name":
		mode.setLang().name = stringValue(value)
	case "aliases":
		mode.setLang().aliases = decodeStrings(value)
	case "disableAutodetect":
		mode.disableAutodetect = value.kind == valueTrue
	case "supersetOf":
		mode.setLang().supersetOf = stringValue(value)
	case "classNameAliases":
		mode.setLang().classNameAliases, _ = r.ref(value).(map[string]string)
	case "compilerExtensions":
		if value.kind != valueArray {
			panic("hljs: compilerExtensions is not an array")
		}
		for _, item := range value.list {
			extension, ok := compilerExtensions[functionName(item)]
			if !ok {
				panic("hljs: unknown compiler extension " + functionName(item))
			}
			props := mode.setLang()
			props.compilerExtensions = append(props.compilerExtensions, extension)
		}
	}
}

// stringValue is a string value's text and "" for any other value.
func stringValue(value snapshotValue) string {
	if value.kind != valueString {
		return ""
	}
	return value.text
}

// functionName is a {"fn":name} value's name and "" for any other value.
func functionName(value snapshotValue) string {
	if value.kind != valueFunction {
		return ""
	}
	return value.text
}

var modePropertyKeys = map[string]modeKeys{
	"begin": keyBegin, "end": keyEnd, "match": keyMatch, "illegal": keyIllegal, "lexemes": keyLexemes, "beforeMatch": keyBeforeMatch,
	"className": keyClassName, "contains": keyContains, "variants": keyVariants, "starts": keyStarts,
	"endsParent": keyEndsParent, "endsWithParent": keyEndsWithParent, "excludeBegin": keyExcludeBegin, "excludeEnd": keyExcludeEnd,
	"returnBegin": keyReturnBegin, "returnEnd": keyReturnEnd, "skip": keySkip, "endSameAsBegin": keyEndSameAsBegin,
	"relevance": keyRelevance, "keywords": keyKeywords, "beginKeywords": keyBeginKeywords, "subLanguage": keySubLanguage,
	"on:begin": keyOnBegin, "on:end": keyOnEnd, "case_insensitive": keyCaseInsensitive, "name": keyName, "aliases": keyAliases,
	"disableAutodetect": keyDisableAutodetect, "supersetOf": keySupersetOf, "classNameAliases": keyClassNameAliases,
	"compilerExtensions": keyCompilerExtensions,
}

// keywordClassCount is the number of classes decodeKeywordsProperty appends for a keywords object's properties: every property but "$pattern".
func keywordClassCount(props []snapshotProp) int {
	n := 0
	for _, prop := range props {
		if prop.key != "$pattern" {
			n++
		}
	}
	return n
}

func decodeKeywordsProperty(object *keywordsObject, key string, value snapshotValue) {
	if key == "$pattern" {
		object.pattern, object.hasPattern = decodePattern(value), true
		return
	}
	class := keywordClass{name: key}
	switch value.kind {
	case valueString:
		class.text = value.text
	case valueRef, valueUndefined, valueRegExp, valueArray, valueFunction:
		class.isList = true
		class.list = decodeStrings(value)
	default:
		panic("hljs: keyword class " + key + " is not a string or an array")
	}
	object.classes = append(object.classes, class)
}

// Text tables from the eager snapshot: RegExp ignoreCase canonicalization and String.prototype.toLowerCase.
var (
	tablesOnce      sync.Once
	canonical       map[rune]rune
	caseClasses     map[rune][]rune
	caseFolded      []rune
	lowerCaseTable  map[rune]string
	systemSymbolSet map[string]bool
)

func loadTables() {
	tablesOnce.Do(func() {
		s := decodeSnapshot(eagerGrammars, snapshotTables)
		canonical = make(map[rune]rune, len(s.Canonicalize))
		for _, pair := range s.Canonicalize {
			canonical[rune(pair[0])] = rune(pair[1])
		}
		canon := func(unit rune) rune {
			if c, ok := canonical[unit]; ok {
				return c
			}
			return unit
		}
		members := map[rune][]rune{}
		for unit := range canonical {
			members[canon(unit)] = append(members[canon(unit)], unit)
		}
		caseClasses = map[rune][]rune{}
		for target, units := range members {
			if canon(target) == target {
				units = append(units, target)
			}
			slices.Sort(units)
			if len(units) < 2 {
				continue
			}
			for _, unit := range units {
				caseClasses[unit] = units
				caseFolded = append(caseFolded, unit)
			}
		}
		slices.Sort(caseFolded)
		lowerCaseTable = make(map[rune]string, len(s.LowerCase))
		for _, mapping := range s.LowerCase {
			lowerCaseTable[mapping.unit] = mapping.text
		}
		systemSymbolSet = make(map[string]bool, len(s.SystemSymbols))
		for _, symbol := range s.SystemSymbols {
			systemSymbolSet[symbol] = true
		}
	})
}

// caseClass lists the code units whose ignoreCase canonical form equals unit's, or nil when unit matches only itself.
func caseClass(unit rune) []rune {
	loadTables()
	return caseClasses[unit]
}

// caseFoldedUnits lists every code unit that matches another under ignoreCase, ascending.
func caseFoldedUnits() []rune {
	loadTables()
	return caseFolded
}

// toLowerCase is String.prototype.toLowerCase over WTF-8. Keywords contain no sigma, so the context-dependent Final_Sigma mapping cannot change a keyword comparison.
func toLowerCase(text string) string {
	ascii := true
	for i := 0; i < len(text); i++ {
		if text[i] >= utf8.RuneSelf {
			ascii = false
			break
		}
	}
	if ascii {
		return strings.ToLower(text)
	}
	loadTables()
	var out strings.Builder
	for len(text) > 0 {
		if len(text) >= 3 && text[0] == 0xed && text[1] >= 0xa0 && text[1] <= 0xbf {
			out.WriteString(text[:3])
			text = text[3:]
			continue
		}
		r, size := utf8.DecodeRuneInString(text)
		if lower, ok := lowerCaseTable[r]; ok && (r != utf8.RuneError || size > 1) {
			out.WriteString(lower)
		} else {
			out.WriteString(text[:size])
		}
		text = text[size:]
	}
	return out.String()
}
